/** E-signature: Send documents for e-signature, follow them and download the signed PDF. */
export class SignatureRequests {

  constructor(private readonly _client: Requester) {
  }

  /**
   * List e-signature requests.
   *
   * E-signature requests – administrators see the whole team, members the ones they created or sent – newest first.
   *
   * `GET /api/v2/signature-requests` – scope `documents:read`
   * @see https://www.helprange.com/developers/api/list-signature-requests
   */
  list(query?: T.ListSignatureRequestsQuery, options?: RequestOptions): Promise<T.ListSignatureRequestsResponse> {
    return this._client.request<T.ListSignatureRequestsResponse>({ method: 'GET', path: `/api/v2/signature-requests`, query, ...options });
  }

  /**
   * Send a document for e-signature.
   *
   * Sends a document from a folder you can open for e-signature (plans with e-signature). A signature page with a block per signer is added at the end; every recipient gets an e-mail with a signing link (counted in the team's API e-mail budget). Form posts can pass repeated signer_email fields instead of signers.
   *
   * `POST /api/v2/signature-requests` – scope `documents:write`
   * Sent with an Idempotency-Key, so retries are safe (set your own with `options.idempotencyKey`).
   * @see https://www.helprange.com/developers/api/create-signature-request
   */
  create(body: T.CreateSignatureRequestBody, options?: RequestOptions): Promise<T.CreateSignatureRequestResponse> {
    return this._client.request<T.CreateSignatureRequestResponse>({ method: 'POST', path: `/api/v2/signature-requests`, body, ...options });
  }

  /**
   * E-signature request details.
   *
   * One request with each recipient's status and the audit trail.
   *
   * `GET /api/v2/signature-requests/{envelope_id}` – scope `documents:read`
   * @see https://www.helprange.com/developers/api/get-signature-request
   */
  get(envelopeId: string, options?: RequestOptions): Promise<T.GetSignatureRequestResponse> {
    return this._client.request<T.GetSignatureRequestResponse>({ method: 'GET', path: `/api/v2/signature-requests/${encodePath(envelopeId)}`, ...options });
  }

  /**
   * Remind signers.
   *
   * E-mails a reminder to the recipients who still have to act – at most once an hour per request (400 otherwise).
   *
   * `POST /api/v2/signature-requests/{envelope_id}/remind` – scope `documents:write`
   * Sent with an Idempotency-Key, so retries are safe (set your own with `options.idempotencyKey`).
   * @see https://www.helprange.com/developers/api/remind-signature-request
   */
  remind(envelopeId: string, options?: RequestOptions): Promise<T.RemindSignatureRequestResponse> {
    return this._client.request<T.RemindSignatureRequestResponse>({ method: 'POST', path: `/api/v2/signature-requests/${encodePath(envelopeId)}/remind`, ...options });
  }

  /**
   * Void an e-signature request.
   *
   * Cancels a sent request: nobody can sign it any more and the waiting recipients are told. Cannot be undone.
   *
   * `POST /api/v2/signature-requests/{envelope_id}/void` – scope `documents:write`
   * Sent with an Idempotency-Key, so retries are safe (set your own with `options.idempotencyKey`).
   * @see https://www.helprange.com/developers/api/void-signature-request
   */
  void(envelopeId: string, body?: T.VoidSignatureRequestBody, options?: RequestOptions): Promise<T.VoidSignatureRequestResponse> {
    return this._client.request<T.VoidSignatureRequestResponse>({ method: 'POST', path: `/api/v2/signature-requests/${encodePath(envelopeId)}/void`, body, ...options });
  }

  /**
   * Signed PDF link.
   *
   * Download link of the signed PDF with the certificate of completion. 409 while not everyone has signed. Requests signed before 2026-11-10 answer with a panel link and a note instead.
   *
   * `GET /api/v2/signature-requests/{envelope_id}/signed-pdf` – scope `documents:read`
   * @see https://www.helprange.com/developers/api/get-signed-pdf
   */
  getSignedPdf(envelopeId: string, options?: RequestOptions): Promise<T.GetSignedPdfResponse> {
    return this._client.request<T.GetSignedPdfResponse>({ method: 'GET', path: `/api/v2/signature-requests/${encodePath(envelopeId)}/signed-pdf`, ...options });
  }
}

/** Data rooms: Data rooms, their index, guests, folders, documents, Q&A and request lists. */
export class DataRooms {
  readonly guests: DataRoomsGuests;
  readonly accessRequests: DataRoomsAccessRequests;
  readonly signatureRequests: DataRoomsSignatureRequests;
  readonly questions: DataRoomsQuestions;
  readonly requestItems: DataRoomsRequestItems;
  readonly folders: DataRoomsFolders;
  readonly documents: DataRoomsDocuments;

  constructor(private readonly _client: Requester) {
    this.guests = new DataRoomsGuests(_client);
    this.accessRequests = new DataRoomsAccessRequests(_client);
    this.signatureRequests = new DataRoomsSignatureRequests(_client);
    this.questions = new DataRoomsQuestions(_client);
    this.requestItems = new DataRoomsRequestItems(_client);
    this.folders = new DataRoomsFolders(_client);
    this.documents = new DataRoomsDocuments(_client);
  }

  /**
   * List data rooms.
   *
   * Data rooms with guest and document counts (administrators: every room; members: the rooms they created).
   *
   * `GET /api/v2/data-rooms` – scope `rooms:read`
   * @see https://www.helprange.com/developers/api/list-data-rooms
   */
  list(options?: RequestOptions): Promise<T.ListDataRoomsResponse> {
    return this._client.request<T.ListDataRoomsResponse>({ method: 'GET', path: `/api/v2/data-rooms`, ...options });
  }

  /**
   * Create a data room.
   *
   * Creates a data room, like "New data room" in the panel, with optional folders (one level – no folders inside folders) and settings. Defaults: watermark on, download off, no screenshot protection, guest notifications on, no NDA, no expiry (a default the plan does not include is left off; a setting you ASK for that the plan does not include: 402 naming the plan). The name must be unique in the team (400). Pro: up to 3 active rooms (402 when the limit is reached); Max, Unlimited, the Deal Room Pass and the trial: unlimited. Next: add documents (Add documents to a data room) and invite guests (Invite a guest) – invitations go out once the room has a document. Answers 201 with the room, including links.guest_link.
   *
   * `POST /api/v2/data-rooms` – scope `rooms:write`
   * Sent with an Idempotency-Key, so retries are safe (set your own with `options.idempotencyKey`).
   * @see https://www.helprange.com/developers/api/create-data-room
   */
  create(body: T.CreateDataRoomBody, options?: RequestOptions): Promise<T.CreateDataRoomResponse> {
    return this._client.request<T.CreateDataRoomResponse>({ method: 'POST', path: `/api/v2/data-rooms`, body, ...options });
  }

  /**
   * Data room details.
   *
   * Settings, links (guest link, panel), guests (views, last visit, NDA status, their own invitation link), documents, freeze status with closing archives, and Q&A counts.
   *
   * `GET /api/v2/data-rooms/{data_room_id}` – scope `rooms:read`
   * @see https://www.helprange.com/developers/api/get-data-room
   */
  get(dataRoomId: number, options?: RequestOptions): Promise<T.GetDataRoomResponse> {
    return this._client.request<T.GetDataRoomResponse>({ method: 'GET', path: `/api/v2/data-rooms/${encodePath(dataRoomId)}`, ...options });
  }

  /**
   * Change a data room.
   *
   * Renames the room (name: what guests see) and / or changes its settings, like the room's Settings window: watermark, download, screenshot protection, notifications, expiry, NDA on / off (nda, nda_id, nda_template, nda_mode), Q&A, access requests, room folders. Only what is sent changes; the room's documents take the new settings (within what each file type allows). Only a setting switched ON is checked against the plan (402) – a room keeps what it has, switching off is always allowed. Turning folders off deletes the room's folders; their documents stay in the room (409 when the room is frozen). Answers with the room.
   *
   * `POST /api/v2/data-rooms/{data_room_id}` – scope `rooms:write`
   * Sent with an Idempotency-Key, so retries are safe (set your own with `options.idempotencyKey`).
   * @see https://www.helprange.com/developers/api/update-data-room
   */
  update(dataRoomId: number, body?: T.UpdateDataRoomBody, options?: RequestOptions): Promise<T.UpdateDataRoomResponse> {
    return this._client.request<T.UpdateDataRoomResponse>({ method: 'POST', path: `/api/v2/data-rooms/${encodePath(dataRoomId)}`, body, ...options });
  }

  /**
   * Delete a data room.
   *
   * Like "Delete data room" in the panel: guests lose access at once and the room's links stop working; the documents stay in their folders. Cannot be undone, so the body must carry "confirm": true – without it the answer is 400 {"error": "confirmation_required", "message"} and nothing is deleted.
   *
   * `POST /api/v2/data-rooms/{data_room_id}/delete` – scope `rooms:write`
   * Sent with an Idempotency-Key, so retries are safe (set your own with `options.idempotencyKey`).
   * @see https://www.helprange.com/developers/api/delete-data-room
   */
  delete(dataRoomId: number, body: T.DeleteDataRoomBody, options?: RequestOptions): Promise<T.DeleteDataRoomResponse> {
    return this._client.request<T.DeleteDataRoomResponse>({ method: 'POST', path: `/api/v2/data-rooms/${encodePath(dataRoomId)}/delete`, body, ...options });
  }

  /**
   * Data room index.
   *
   * The room's numbered index (1, 1.1 …) in the structure guests see – always one level of folders. With room folders on, folder nodes are the room's folders (room_folder_id); otherwise, with "Show Folders" on, the folder the documents come from (folder_id, plus subfolder_id for "Folder / Subfolder"). The numbers exist even while numbering is off for guests (index_numbering false).
   *
   * `GET /api/v2/data-rooms/{data_room_id}/index` – scope `rooms:read`
   * @see https://www.helprange.com/developers/api/get-data-room-index
   */
  getIndex(dataRoomId: number, options?: RequestOptions): Promise<T.GetDataRoomIndexResponse> {
    return this._client.request<T.GetDataRoomIndexResponse>({ method: 'GET', path: `/api/v2/data-rooms/${encodePath(dataRoomId)}/index`, ...options });
  }
}

